        cerr << "Error: Invalid input. Please enter non-negative integers." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    // Error handling for invalid inputs
    if (cin.fail() || num_elements <= 0) {
        cerr << "Error: Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    vector<int> sequence = fibonacci(num_elements, first_element, second_element);
    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

